#!/usr/bin/env bash
set -euo pipefail

if [[ "${1:-}" == "--systemd-service" ]]; then
  app_root="${YINSHI_APP_ROOT:-/opt/yinshi}"
  service_user="${YINSHI_SERVICE_USER:-user}"
  status_path="${YINSHI_PI_UPDATE_STATUS_PATH:-$app_root/.runtime/pi-package-update.json}"
  runuser_bin="$(command -v runuser || true)"

  if [[ "$(id -u)" -ne 0 ]]; then
    echo "--systemd-service must run as root" >&2
    exit 1
  fi
  if [[ ! -x "$runuser_bin" ]]; then
    echo "runuser is required for the systemd service wrapper" >&2
    exit 1
  fi

  "$runuser_bin" -u "$service_user" -- env \
    YINSHI_APP_ROOT="$app_root" \
    YINSHI_PI_UPDATE_STATUS_PATH="$status_path" \
    "$app_root/scripts/update-pi-package.sh"

  updated="$(STATUS_PATH="$status_path" node --input-type=module <<'NODE'
import fs from "node:fs";
const statusPath = process.env.STATUS_PATH;
let updated = false;
try {
  const payload = JSON.parse(fs.readFileSync(statusPath, "utf-8"));
  updated = payload.updated === true;
} catch {
  updated = false;
}
process.stdout.write(updated ? "true" : "false");
NODE
)"

  if [[ "$updated" == "true" ]]; then
    systemctl restart yinshi-sidecar.service
    systemctl restart yinshi-backend.service
  fi
  exit 0
fi

package_name="${PI_PACKAGE_NAME:-@mariozechner/pi-coding-agent}"
app_root="${YINSHI_APP_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
sidecar_dir="${YINSHI_SIDECAR_DIR:-$app_root/sidecar}"
container_image="${YINSHI_CONTAINER_IMAGE:-yinshi-sidecar:latest}"
runtime_dir="${YINSHI_RUNTIME_DIR:-$app_root/.runtime}"
status_path="${YINSHI_PI_UPDATE_STATUS_PATH:-$runtime_dir/pi-package-update.json}"
lock_path="${YINSHI_PI_UPDATE_LOCK_PATH:-$runtime_dir/pi-package-update.lock}"

log() {
  printf '[%s] %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$*"
}

write_status() {
  local status_value="$1"
  local updated_value="$2"
  local previous_version="$3"
  local current_version="$4"
  local latest_version="$5"
  local message_value="$6"

  STATUS_PATH="$status_path" \
  STATUS_VALUE="$status_value" \
  UPDATED_VALUE="$updated_value" \
  PREVIOUS_VERSION="$previous_version" \
  CURRENT_VERSION="$current_version" \
  LATEST_VERSION="$latest_version" \
  MESSAGE_VALUE="$message_value" \
  node --input-type=module <<'NODE'
import fs from "node:fs";
import path from "node:path";

const statusPath = process.env.STATUS_PATH;
if (!statusPath) {
  throw new Error("STATUS_PATH is required");
}
const payload = {
  checked_at: new Date().toISOString(),
  status: process.env.STATUS_VALUE || "unknown",
  previous_version: process.env.PREVIOUS_VERSION || null,
  current_version: process.env.CURRENT_VERSION || null,
  latest_version: process.env.LATEST_VERSION || null,
  updated: process.env.UPDATED_VALUE === "true",
  message: process.env.MESSAGE_VALUE || null,
};
fs.mkdirSync(path.dirname(statusPath), { recursive: true });
const temporaryPath = `${statusPath}.tmp`;
fs.writeFileSync(temporaryPath, `${JSON.stringify(payload, null, 2)}\n`, "utf-8");
fs.renameSync(temporaryPath, statusPath);
NODE
}

read_installed_version() {
  local package_root="$1"
  PACKAGE_ROOT="$package_root" PACKAGE_NAME="$package_name" node --input-type=module <<'NODE'
import fs from "node:fs";
import path from "node:path";

const packageRoot = process.env.PACKAGE_ROOT;
const packageName = process.env.PACKAGE_NAME;
if (!packageRoot || !packageName) {
  process.exit(2);
}
let currentPath = path.join(packageRoot, "src");
while (true) {
  const packageJsonPath = path.join(currentPath, "node_modules", packageName, "package.json");
  if (fs.existsSync(packageJsonPath)) {
    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf-8"));
    if (packageJson.name === packageName) {
      process.stdout.write(packageJson.version || "");
      process.exit(packageJson.version ? 0 : 4);
    }
  }
  const parentPath = path.dirname(currentPath);
  if (parentPath === currentPath) {
    break;
  }
  currentPath = parentPath;
}
process.exit(5);
NODE
}

copy_sidecar_context() {
  local target_dir="$1"
  cp "$sidecar_dir/package.json" "$target_dir/package.json"
  cp "$sidecar_dir/package-lock.json" "$target_dir/package-lock.json"
  cp "$sidecar_dir/Dockerfile" "$target_dir/Dockerfile"
  cp -R "$sidecar_dir/src" "$target_dir/src"
}

run_smoke_test() {
  local target_dir="$1"
  (cd "$target_dir" && node --input-type=module <<'NODE'
import { pathToFileURL } from "node:url";
import { AuthStorage, ModelRegistry } from "@mariozechner/pi-coding-agent";

const registry = new ModelRegistry(AuthStorage.inMemory(), null);
const models = registry.getAll();
if (!Array.isArray(models)) {
  throw new Error("Model registry did not return an array");
}
if (models.length === 0) {
  throw new Error("Model registry returned no models");
}
const sidecarModule = await import(pathToFileURL(`${process.cwd()}/src/sidecar.js`).href);
if (typeof sidecarModule.YinshiSidecar !== "function") {
  throw new Error("YinshiSidecar export is missing");
}
const sidecar = new sidecarModule.YinshiSidecar();
sidecar.cleanup();
NODE
  )
}

replace_node_modules() {
  local source_node_modules="$1"
  local target_node_modules="$2"
  local next_node_modules="$target_node_modules.next"
  local previous_node_modules="$target_node_modules.previous"

  rm -rf "$next_node_modules" "$previous_node_modules" || return 1
  cp -a "$source_node_modules" "$next_node_modules" || return 1
  if [[ -d "$target_node_modules" ]]; then
    mv "$target_node_modules" "$previous_node_modules" || {
      rm -rf "$next_node_modules"
      return 1
    }
  fi
  mv "$next_node_modules" "$target_node_modules" || {
    if [[ -d "$previous_node_modules" ]]; then
      mv "$previous_node_modules" "$target_node_modules" || true
    fi
    rm -rf "$next_node_modules"
    return 1
  }
  rm -rf "$previous_node_modules" || return 1
}

previous_version=""
latest_version=""
resolved_version=""
temporary_dir=""

fail_update() {
  local message_value="$1"
  write_status "failed" "false" "$previous_version" "$resolved_version" "$latest_version" "$message_value"
  echo "$message_value" >&2
  exit 1
}

mkdir -p "$runtime_dir"
if ! command -v flock >/dev/null 2>&1; then
  fail_update "flock is required"
fi
exec 9>"$lock_path"
if ! flock -n 9; then
  log "Another pi package update is already running; exiting."
  exit 0
fi

cleanup() {
  if [[ -n "$temporary_dir" && -d "$temporary_dir" ]]; then
    rm -rf "$temporary_dir"
  fi
}
trap cleanup EXIT

if [[ ! -d "$sidecar_dir" ]]; then
  fail_update "Sidecar directory not found: $sidecar_dir"
fi
if ! command -v npm >/dev/null 2>&1; then
  fail_update "npm is required"
fi
if ! command -v podman >/dev/null 2>&1; then
  fail_update "podman is required to rebuild tenant sidecar image"
fi

previous_version="$(read_installed_version "$sidecar_dir" || true)"
if ! latest_version="$(npm view "$package_name" version --silent)"; then
  fail_update "npm view failed for $package_name"
fi
if [[ -z "$latest_version" ]]; then
  fail_update "npm did not return a latest version for $package_name"
fi

if [[ -n "$previous_version" && "$previous_version" == "$latest_version" ]]; then
  write_status "current" "false" "$previous_version" "$previous_version" "$latest_version" "$package_name is already current"
  log "$package_name is already current at $latest_version."
  exit 0
fi

temporary_dir="$(mktemp -d)"
copy_sidecar_context "$temporary_dir"
log "Updating $package_name from ${previous_version:-not installed} to $latest_version in temporary build context."
if ! npm install --prefix "$temporary_dir" --omit=dev --no-audit --no-fund "$package_name@$latest_version"; then
  fail_update "npm install failed for $package_name@$latest_version"
fi
if ! resolved_version="$(read_installed_version "$temporary_dir")"; then
  fail_update "Could not read installed version after npm install"
fi
if [[ "$resolved_version" != "$latest_version" ]]; then
  fail_update "Resolved $resolved_version instead of npm latest $latest_version"
fi

if ! run_smoke_test "$temporary_dir"; then
  fail_update "Sidecar smoke test failed for $package_name@$latest_version"
fi
if ! podman build -t "$container_image" "$temporary_dir"; then
  fail_update "Podman image build failed for $container_image"
fi
if ! replace_node_modules "$temporary_dir/node_modules" "$sidecar_dir/node_modules"; then
  fail_update "Failed to replace host sidecar node_modules"
fi
write_status "updated" "true" "$previous_version" "$resolved_version" "$latest_version" "Updated $package_name to $resolved_version and rebuilt $container_image"
log "Updated $package_name to $resolved_version and rebuilt $container_image."

"""CRUD endpoints for repositories."""

import logging
import sqlite3
import uuid
from pathlib import Path
from typing import Any

from fastapi import APIRouter, HTTPException, Request

from yinshi.api.deps import check_owner, get_db_for_request, get_tenant, get_user_email
from yinshi.config import get_settings
from yinshi.exceptions import (
    GitError,
    GitHubAccessError,
    GitHubAccessNotGrantedError,
    GitHubAppError,
    GitHubConnectRequiredError,
)
from yinshi.models import RepoCreate, RepoOut, RepoUpdate
from yinshi.rate_limit import limiter
from yinshi.services.git import clone_local_repo, clone_repo, validate_local_repo
from yinshi.services.github_app import GitHubCloneAccess, resolve_github_clone_access
from yinshi.services.workspace import delete_workspace
from yinshi.utils.paths import is_path_inside

logger = logging.getLogger(__name__)
router = APIRouter(prefix="/api/repos", tags=["repos"])

# Only these columns can be updated via PATCH
_UPDATABLE_COLUMNS = {"name", "custom_prompt", "agents_md"}


def _validate_local_path(path_str: str) -> str:
    """Validate and resolve a local path, checking against allowed base.

    Fail-closed: if ``allowed_repo_base`` is not configured, all local
    imports are rejected.
    """
    settings = get_settings()
    if not settings.allowed_repo_base:
        raise HTTPException(
            status_code=400,
            detail="Local repo imports are disabled (allowed_repo_base not set)",
        )
    resolved = str(Path(path_str).resolve())
    if not is_path_inside(resolved, settings.allowed_repo_base):
        raise HTTPException(status_code=400, detail="Path not in allowed directory")
    return resolved


def _check_repo_owner(row: sqlite3.Row, request: Request) -> None:
    """In legacy mode, verify the authenticated user owns the repo."""
    tenant = get_tenant(request)
    if not tenant:
        check_owner(row["owner_email"], get_user_email(request))


def _github_connect_url(request: Request) -> str | None:
    """Return the GitHub connect URL when the feature is usable for this request."""
    settings = get_settings()
    if not settings.github_app_slug:
        return None
    if get_tenant(request) is None:
        return None
    return "/auth/github/install"


def _github_http_exception(error: GitHubAccessError) -> HTTPException:
    """Convert a GitHub access error into a structured HTTP error."""
    detail = {
        "code": error.code,
        "message": str(error),
        "connect_url": error.connect_url,
        "manage_url": error.manage_url,
    }
    return HTTPException(status_code=400, detail=detail)


async def _resolve_clone_access(
    request: Request,
    remote_url: str,
) -> GitHubCloneAccess | None:
    """Resolve GitHub clone credentials for a remote, if applicable."""
    tenant = get_tenant(request)
    user_id = tenant.user_id if tenant else None
    try:
        return await resolve_github_clone_access(user_id, remote_url)
    except GitHubAccessError as error:
        raise _github_http_exception(error)
    except GitHubAppError as error:
        logger.exception("GitHub integration failed while resolving %s", remote_url)
        raise HTTPException(status_code=502, detail=str(error))


def _github_clone_failure(
    request: Request,
    clone_access: GitHubCloneAccess,
) -> HTTPException:
    """Translate an anonymous GitHub clone failure into an actionable error."""
    assert clone_access.access_token is None, "clone failure helper expects anonymous access"
    if clone_access.manage_url:
        return _github_http_exception(
            GitHubAccessNotGrantedError(
                "Grant this repository to the connected GitHub installation and try again.",
                manage_url=clone_access.manage_url,
            )
        )
    return _github_http_exception(
        GitHubConnectRequiredError(
            "Connect GitHub to import this private repository.",
            connect_url=_github_connect_url(request),
        )
    )


@router.get("", response_model=list[RepoOut])
def list_repos(request: Request) -> list[dict[str, Any]]:
    """List all imported repositories."""
    tenant = get_tenant(request)
    email = None if tenant else get_user_email(request)

    with get_db_for_request(request) as db:
        if email:
            rows = db.execute(
                "SELECT * FROM repos WHERE owner_email = ? OR owner_email IS NULL "
                "ORDER BY created_at DESC",
                (email,),
            ).fetchall()
        else:
            rows = db.execute("SELECT * FROM repos ORDER BY created_at DESC").fetchall()
        return [dict(r) for r in rows]


@router.post("", response_model=RepoOut, status_code=201)
@limiter.limit("10/hour")
async def import_repo(body: RepoCreate, request: Request) -> dict[str, Any]:
    """Import a repository (clone from URL or register local path)."""
    tenant = get_tenant(request)
    settings = get_settings()
    normalized_remote_url = body.remote_url
    clone_access: GitHubCloneAccess | None = None
    repo_id: str | None = None

    if body.local_path:
        resolved = _validate_local_path(body.local_path)
        if not Path(resolved).is_dir():
            raise HTTPException(status_code=400, detail="Path does not exist")
        is_repo = await validate_local_repo(resolved)
        if not is_repo:
            raise HTTPException(status_code=400, detail="Not a valid git repository")
        if tenant and settings.container_enabled:
            repo_id = uuid.uuid4().hex
            root_path = str(Path(tenant.data_dir) / "repos" / repo_id)
            try:
                await clone_local_repo(resolved, root_path)
            except GitError as error:
                raise HTTPException(status_code=400, detail=str(error)) from error
        else:
            root_path = resolved
    elif body.remote_url:
        clone_access = await _resolve_clone_access(request, body.remote_url)
        access_token = None
        if clone_access is not None:
            normalized_remote_url = clone_access.clone_url
            access_token = clone_access.access_token

        # Sanitize name to prevent path traversal.
        safe_name = Path(body.name).name
        if not safe_name or safe_name != body.name or ".." in body.name:
            raise HTTPException(
                status_code=400,
                detail="Invalid repository name (must be a simple directory name)",
            )

        if tenant:
            clone_dir = str(Path(tenant.data_dir) / "repos" / safe_name)
        else:
            clone_dir = str(Path.home() / ".yinshi" / "repos" / safe_name)
        try:
            root_path = await clone_repo(
                normalized_remote_url or body.remote_url,
                clone_dir,
                access_token=access_token,
            )
        except GitError as e:
            if clone_access is not None and clone_access.access_token is None:
                if clone_access.repository_installation_id is not None:
                    raise _github_clone_failure(request, clone_access)
                if clone_access.manage_url is not None:
                    raise _github_clone_failure(request, clone_access)
            else:
                assert clone_access is None or clone_access.access_token is not None
            raise HTTPException(status_code=400, detail=str(e))
    else:
        raise HTTPException(status_code=400, detail="Either remote_url or local_path is required")

    installation_id = None
    if clone_access is not None and clone_access.access_token is not None:
        installation_id = clone_access.installation_id
    with get_db_for_request(request) as db:
        if tenant:
            if repo_id is None:
                cursor = db.execute(
                    """INSERT INTO repos (name, remote_url, root_path, custom_prompt, agents_md, installation_id)
                       VALUES (?, ?, ?, ?, ?, ?)""",
                    (
                        body.name,
                        normalized_remote_url,
                        root_path,
                        body.custom_prompt,
                        body.agents_md,
                        installation_id,
                    ),
                )
            else:
                cursor = db.execute(
                    """INSERT INTO repos (id, name, remote_url, root_path, custom_prompt, agents_md, installation_id)
                       VALUES (?, ?, ?, ?, ?, ?, ?)""",
                    (
                        repo_id,
                        body.name,
                        normalized_remote_url,
                        root_path,
                        body.custom_prompt,
                        body.agents_md,
                        installation_id,
                    ),
                )
        else:
            email = get_user_email(request)
            cursor = db.execute(
                """INSERT INTO repos (name, remote_url, root_path, custom_prompt, agents_md, owner_email, installation_id)
                   VALUES (?, ?, ?, ?, ?, ?, ?)""",
                (
                    body.name,
                    normalized_remote_url,
                    root_path,
                    body.custom_prompt,
                    body.agents_md,
                    email,
                    installation_id,
                ),
            )
        db.commit()
        row = db.execute("SELECT * FROM repos WHERE rowid = ?", (cursor.lastrowid,)).fetchone()
        return dict(row)


@router.get("/{repo_id}", response_model=RepoOut)
def get_repo(repo_id: str, request: Request) -> dict[str, Any]:
    """Get a single repository by ID."""
    with get_db_for_request(request) as db:
        row = db.execute("SELECT * FROM repos WHERE id = ?", (repo_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Repo not found")
        _check_repo_owner(row, request)
        return dict(row)


@router.patch("/{repo_id}", response_model=RepoOut)
def update_repo(
    repo_id: str,
    body: RepoUpdate,
    request: Request,
) -> dict[str, Any]:
    """Update a repository."""
    with get_db_for_request(request) as db:
        row = db.execute("SELECT * FROM repos WHERE id = ?", (repo_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Repo not found")
        _check_repo_owner(row, request)

        updates = {
            k: v for k, v in body.model_dump(exclude_unset=True).items() if k in _UPDATABLE_COLUMNS
        }
        if updates:
            set_clause = ", ".join(f"{k} = ?" for k in updates)
            values = list(updates.values()) + [repo_id]
            db.execute(f"UPDATE repos SET {set_clause} WHERE id = ?", values)
            db.commit()
        row = db.execute("SELECT * FROM repos WHERE id = ?", (repo_id,)).fetchone()
        return dict(row)


@router.delete("/{repo_id}", status_code=204)
async def delete_repo(repo_id: str, request: Request) -> None:
    """Delete a repository and all its workspaces."""
    with get_db_for_request(request) as db:
        row = db.execute("SELECT * FROM repos WHERE id = ?", (repo_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Repo not found")
        _check_repo_owner(row, request)
        workspace_rows = db.execute(
            "SELECT id FROM workspaces WHERE repo_id = ?",
            (repo_id,),
        ).fetchall()
        for workspace in workspace_rows:
            try:
                await delete_workspace(db, workspace["id"], tenant=get_tenant(request))
            except Exception:
                logger.warning(
                    "Failed to delete workspace %s while deleting repo %s",
                    workspace["id"],
                    repo_id,
                    exc_info=True,
                )
        db.execute("DELETE FROM repos WHERE id = ?", (repo_id,))
        db.commit()

