      // The SDK's `tools` option is an allow-list of tool names. Pass Yinshi's
      // tool implementations as `customTools` so they replace the built-ins
      // while keeping read/bash/edit/write active for the model.
      customTools: createYinshiCodingTools(cwd, gitAuth),
      sessionManager,
      settingsManager,
      authStorage: sessionAuth,
      modelRegistry: sessionRegistry,
    };
    if (agentDir) {
      sessionOptions.agentDir = agentDir;
    }

    const { session } = await createAgentSession(sessionOptions);
    // Bind a web-friendly UI context so extensions (e.g. rtk-metrics) whose
    // handlers call ctx.ui.notify() can surface output in the chat. Without
    // this binding, notify() calls silently vanish in RPC mode.
    const runner = session.extensionRunner;
    console.log(
      `[sidecar] session ${sessionId} extensionRunner=${runner ? "present" : "MISSING"}`,
    );
    if (runner) {
      runner.setUIContext(createWebUIContext(sessionId, socket, model));
      console.log(`[sidecar] session ${sessionId} UI context bound`);
    }
    if (resetWarning) {
      sendStatusToSocket(
        socket,
        sessionId,
        "context_reset",
        resetWarning,
        "warning",
      );
    }
    console.log(
      `[sidecar] Created pi session ${sessionId} with model ${model.name || model.id}`
      + (agentDir ? ` and agentDir ${agentDir}` : "")
      + (openedPiSessionFile
        ? ` and piSessionFile ${openedPiSessionFile}`
        : ""),
    );
    return { session, model, piSessionFile: openedPiSessionFile };
  }

  async warmupSession(sessionId, socket, options) {
    if (this.activeSessions.has(sessionId)) {
      console.log(`[sidecar] Session ${sessionId} already exists`);
      return;
    }

    const modelRef = options.model || DEFAULT_MODEL_REF;
    const cwd = options.cwd || process.cwd();
    const providerAuth = options.providerAuth || null;
    const providerConfig = options.providerConfig || null;
    const gitAuth = options.gitAuth || null;
    const agentDir = options.agentDir || null;
    const importedSettings = options.settings || null;

    try {
      const requestedPiSessionFile = normalizePiSessionFile(options.piSessionFile || null);
      const {
        session: piSession,
        model,
        piSessionFile: normalizedPiSessionFile,
      } = await this._createPiSession(
        sessionId,
        socket,
        modelRef,
        cwd,
        providerAuth,
        providerConfig,
        gitAuth,
        agentDir,
        importedSettings,
        requestedPiSessionFile,
      );
      this.activeSessions.set(sessionId, {
        piSession,
        model,
        modelRef,
        cwd,
        providerAuth,
        providerConfig,
        gitAuth,
        importedSettings,
        piSessionFile: normalizedPiSessionFile,
        unsubscribe: null,
        cancelRequested: false,
      });
      console.log(`[sidecar] Warmed up session ${sessionId}`);
    } catch (err) {
      console.error(`[sidecar] Warmup failed: ${err.message}`);
      sendToSocket(socket, { id: sessionId, type: "error", error: err.message });
    }
  }

  async processQuery(sessionId, socket, prompt, options) {
    const modelRef = options.model || DEFAULT_MODEL_REF;
    const cwd = options.cwd || process.cwd();
    const providerAuth = options.providerAuth || null;
    const providerConfig = options.providerConfig || null;
    const gitAuth = options.gitAuth || null;
    const agentDir = options.agentDir || null;
    const importedSettings = options.settings || null;
    let entry = this.activeSessions.get(sessionId);
    let clearFinalizeTimer = () => {};
    console.log(
      `[sidecar] processQuery session=${sessionId} model=${modelRef} hasEntry=${!!entry} promptLen=${prompt?.length ?? 0}`,
    );

    try {
      const requestedPiSessionFile = normalizePiSessionFile(options.piSessionFile || null);
      const authChanged = JSON.stringify(entry?.providerAuth || null) !== JSON.stringify(providerAuth);
      const configChanged = JSON.stringify(entry?.providerConfig || null) !== JSON.stringify(providerConfig);
      const gitAuthChanged = JSON.stringify(entry?.gitAuth || null) !== JSON.stringify(gitAuth);
      const settingsChanged = JSON.stringify(entry?.importedSettings || null)
        !== JSON.stringify(importedSettings);
      const piSessionFileChanged = (entry?.piSessionFile || null) !== requestedPiSessionFile;
      if (
        !entry
        || entry.modelRef !== modelRef
        || authChanged
        || configChanged
        || gitAuthChanged
        || settingsChanged
        || piSessionFileChanged
      ) {
        if (entry) {
          if (entry.unsubscribe) {
            entry.unsubscribe();
          }
          entry.piSession.dispose();
        }
        const {
          session: piSession,
          model,
          piSessionFile: normalizedPiSessionFile,
        } = await this._createPiSession(
          sessionId,
          socket,
          modelRef,
          cwd,
          providerAuth,
          providerConfig,
          gitAuth,
          agentDir,
          importedSettings,
          requestedPiSessionFile,
        );
        entry = {
          piSession,
          model,
          modelRef,
          cwd,
          providerAuth,
          providerConfig,
          gitAuth,
          importedSettings,
          piSessionFile: normalizedPiSessionFile,
          unsubscribe: null,
          cancelRequested: false,
        };
        this.activeSessions.set(sessionId, entry);
      }

      const { piSession, model } = entry;

      if (entry.unsubscribe) {
        entry.unsubscribe();
      }

      let usage = null;
      // When pi handles a prompt as an extension command (text starting with
      // "/" that matches a registered command), it returns from prompt()
      // without firing "agent_end". The stream would hang forever waiting
      // for a "result" event. Track whether agent_end fired so we can emit
      // a synthetic one after prompt() resolves.
      let agentEndEmitted = false;
      let resultSent = false;
      let pendingResult = null;
      let compactionActive = false;
      let finalizeTimer = null;

      const buildResultMessage = (resultUsage) => ({
        id: sessionId,
        type: "message",
        data: {
          type: "result",
          usage: resultUsage || {},
          provider: model.provider,
          model: `${model.provider}/${model.id}`,
        },
      });

      clearFinalizeTimer = () => {
        if (finalizeTimer) {
          clearTimeout(finalizeTimer);
          finalizeTimer = null;
        }
      };

      const schedulePendingResult = () => {
        clearFinalizeTimer();
        finalizeTimer = setTimeout(() => {
          finalizeTimer = null;
          if (resultSent || compactionActive || !pendingResult) {
            return;
          }
          sendToSocket(socket, pendingResult);
          pendingResult = null;
          resultSent = true;
        }, 0);
      };

      entry.unsubscribe = piSession.subscribe((event) => {
        // Temporary diagnostic so we can see every event pi emits while we
        // track down why turns never reach the browser.
        console.log(`[sidecar][event] session=${sessionId} type=${event.type}`);
        switch (event.type) {
          case "message_update": {
            const assistantEvent = event.assistantMessageEvent;
            if (assistantEvent.type === "text_delta") {
              sendToSocket(socket, {
                id: sessionId,
                type: "message",
                data: {
                  type: "assistant",
                  message: {
                    content: [{ type: "text", text: assistantEvent.delta }],
                  },
                },
              });
            } else if (assistantEvent.type === "thinking_delta") {
              sendToSocket(socket, {
                id: sessionId,
                type: "message",
                data: {
                  type: "assistant",
                  message: {
                    content: [
                      { type: "thinking", thinking: assistantEvent.delta },
                    ],
                  },
                },
              });
            }
            break;
          }
          case "tool_execution_start":
            sendToSocket(socket, {
              id: sessionId,
              type: "message",
              data: {
                type: "tool_use",
                id: event.toolCallId,
                toolName: event.toolName,
                toolInput: event.args,
              },
            });
            break;
          case "tool_execution_update":
            sendToSocket(socket, {
              id: sessionId,
              type: "tool_result",
              tool_use_id: event.toolCallId,
              content: stringifyToolResult(event.partialResult),
              partial: true,
            });
            break;
          case "tool_execution_end":
            sendToSocket(socket, {
              id: sessionId,
              type: "tool_result",
              tool_use_id: event.toolCallId,
              content: stringifyToolResult(event.result),
              is_error: event.isError === true,
            });
            break;
          case "turn_end":
            if (event.message && event.message.usage) {
              const eventUsage = event.message.usage;
              usage = {
                input_tokens: eventUsage.input || 0,
                output_tokens: eventUsage.output || 0,
                cache_read_input_tokens: eventUsage.cacheRead || 0,
                cache_creation_input_tokens: eventUsage.cacheWrite || 0,
              };
            }
            break;
          case "agent_end":
            pendingResult = buildResultMessage(usage);
            usage = null;
            agentEndEmitted = true;
            schedulePendingResult();
            break;
          case "auto_retry_start":
            pendingResult = null;
            clearFinalizeTimer();
            console.log(
              `[sidecar] Retrying (attempt ${event.attempt}/${event.maxAttempts}): ${event.errorMessage}`,
            );
            sendStatusToSocket(
              socket,
              sessionId,
              "retrying",
              `Retrying after provider error (attempt ${event.attempt}/${event.maxAttempts})...`,
            );
            break;
          case "auto_retry_end":
            sendStatusToSocket(
              socket,
              sessionId,
              event.success ? "retry_complete" : "retry_failed",
              event.success ? "Retry complete." : "Retry failed.",
              event.success ? "info" : "warning",
            );
            break;
          case "compaction_start":
            compactionActive = true;
            clearFinalizeTimer();
            console.log("[sidecar] Compacting context...");
            sendStatusToSocket(
              socket,
              sessionId,
              "compacting",
              "Compacting context...",
              "info",
              { reason: event.reason },
            );
            break;
          case "compaction_end":
            compactionActive = false;
            if (event.willRetry) {
              pendingResult = null;
            }
            sendStatusToSocket(
              socket,
              sessionId,
              event.errorMessage ? "compaction_failed" : "compacted",
              event.errorMessage || "Context compacted.",
              event.errorMessage ? "warning" : "info",
              {
                reason: event.reason,
                willRetry: event.willRetry === true,
                aborted: event.aborted === true,
              },
            );
            if (!event.willRetry) {
              schedulePendingResult();
            }
            break;
        }
      });

      console.log(`[sidecar] piSession.prompt start session=${sessionId}`);
      await piSession.prompt(prompt);
      console.log(`[sidecar] piSession.prompt end session=${sessionId}`);
      // Clear cancelRequested after normal completion
      entry.cancelRequested = false;

      // Pi returns from prompt() without firing agent_end when it handles an
      // extension command inline (e.g. `/rtk-stats`). Synthesise the result
      // event so the client stream loop terminates cleanly instead of hanging.
      if (!agentEndEmitted && !resultSent) {
        console.log(`[sidecar] synthesising result for session ${sessionId}`);
        sendToSocket(socket, buildResultMessage(usage));
        resultSent = true;
      }
    } catch (err) {
      clearFinalizeTimer();
      const errorMessage = err instanceof Error ? err.message : String(err);
      if (entry?.cancelRequested) {
        console.log(`[sidecar] Session ${sessionId} cancelled by user`);
        sendToSocket(socket, {
          id: sessionId,
          type: "cancelled",
        });
        // Clear cancelRequested after handling cancellation
        entry.cancelRequested = false;
      } else {
        console.error(`[sidecar] Error in session ${sessionId}:`, errorMessage);
        sendToSocket(socket, {
          id: sessionId,
          type: "error",
          error: errorMessage,
        });
      }
    }
  }

  async cancelSession(sessionId) {
    const entry = this.activeSessions.get(sessionId);
    if (!entry) {
      console.log(`[sidecar] Session ${sessionId} not found`);
      return;
    }
    console.log(`[sidecar] Cancelling session ${sessionId}`);
    entry.cancelRequested = true;
    entry.piSession.abortCompaction();
    entry.piSession.abortRetry();
    await entry.piSession.abort();
  }

  cleanup() {
    try {
      if (fs.existsSync(this.socketPath)) {
        fs.unlinkSync(this.socketPath);
      }
    } catch {
      // ignore cleanup races
    }

    if (this.server) {
      try {
        this.server.close();
      } catch {
        // ignore cleanup races
      }
    }

    for (const [, entry] of this.activeSessions) {
      try {
        if (entry.unsubscribe) {
          entry.unsubscribe();
        }
        entry.piSession.dispose();
      } catch {
        // ignore cleanup races
      }
    }
    this.activeSessions.clear();
    this.activeOAuthFlows.clear();
    for (const [, entry] of this.activeTerminals) {
      try {
        entry.terminal.kill();
      } catch {
        // ignore cleanup races
      }
    }
    this.activeTerminals.clear();

    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
      this.healthCheckInterval = null;
    }
  }
}

import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import test from "node:test";

const gitGuardPath = path.resolve("bin", "git");
const realGitPath = "/usr/bin/git";

function runGit(args, cwd) {
  return spawnSync(gitGuardPath, args, {
    cwd,
    encoding: "utf8",
  });
}

function runRealGit(args, cwd) {
  return spawnSync(realGitPath, args, {
    cwd,
    encoding: "utf8",
  });
}

function createRepo() {
  const repoPath = fs.mkdtempSync(path.join(os.tmpdir(), "yinshi-git-guard-test-"));
  assert.equal(runGit(["init"], repoPath).status, 0);
  assert.equal(runGit(["config", "user.email", "test@example.com"], repoPath).status, 0);
  assert.equal(runGit(["config", "user.name", "Test User"], repoPath).status, 0);
  fs.writeFileSync(path.join(repoPath, "README.md"), "# Test\n", "utf8");
  assert.equal(runGit(["add", "README.md"], repoPath).status, 0);
  assert.equal(runGit(["commit", "-m", "init"], repoPath).status, 0);
  return repoPath;
}

test("git guard blocks env commits even when hooks are disabled", () => {
  const repoPath = createRepo();
  try {
    fs.writeFileSync(path.join(repoPath, ".env"), "TOKEN=secret\n", "utf8");
    assert.equal(runGit(["add", "-f", ".env"], repoPath).status, 0);

    const commit = runGit(["commit", "--no-verify", "-m", "try env"], repoPath);

    assert.notEqual(commit.status, 0);
    assert.match(commit.stderr, /Yinshi blocks Git operations/);
  } finally {
    fs.rmSync(repoPath, { recursive: true, force: true });
  }
});

test("git guard blocks pushes with tracked env files before contacting remote", () => {
  const repoPath = createRepo();
  try {
    fs.writeFileSync(path.join(repoPath, ".env"), "TOKEN=secret\n", "utf8");
    assert.equal(runRealGit(["add", "-f", ".env"], repoPath).status, 0);
    assert.equal(runRealGit(["commit", "--no-verify", "-m", "force env"], repoPath).status, 0);

    const push = runGit(["push", "https://example.invalid/repo.git", "HEAD:main"], repoPath);

    assert.notEqual(push.status, 0);
    assert.match(push.stderr, /Yinshi blocks Git operations/);
  } finally {
    fs.rmSync(repoPath, { recursive: true, force: true });
  }
});

import assert from "node:assert/strict";
import fs from "node:fs";
import net from "node:net";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import * as pty from "node-pty";

import { YinshiSidecar, buildTerminalEnvironment } from "../src/sidecar.js";

function createMessageReader(socket) {
  let buffer = "";
  const messages = [];
  const waiters = [];

  function deliver(message) {
    const waiter = waiters.shift();
    if (!waiter) {
      messages.push(message);
      return;
    }
    clearTimeout(waiter.timer);
    waiter.resolve(message);
  }

  function rejectWaiters(error) {
    while (waiters.length > 0) {
      const waiter = waiters.shift();
      clearTimeout(waiter.timer);
      waiter.reject(error);
    }
  }

  function onData(chunk) {
    buffer += chunk.toString("utf8");
    let newline = buffer.indexOf("\n");
    while (newline !== -1) {
      const line = buffer.slice(0, newline).trim();
      buffer = buffer.slice(newline + 1);
      if (line) {
        deliver(JSON.parse(line));
      }
      newline = buffer.indexOf("\n");
    }
  }

  function onError(error) {
    rejectWaiters(error);
  }

  socket.on("data", onData);
  socket.on("error", onError);

  return {
    next(timeoutMs = 3000) {
      const message = messages.shift();
      if (message) {
        return Promise.resolve(message);
      }
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          const index = waiters.findIndex((waiter) => waiter.resolve === resolve);
          if (index !== -1) {
            waiters.splice(index, 1);
          }
          reject(new Error("timed out waiting for sidecar message"));
        }, timeoutMs);
        waiters.push({ resolve, reject, timer });
      });
    },
    dispose() {
      socket.off("data", onData);
      socket.off("error", onError);
      rejectWaiters(new Error("message reader disposed"));
    },
  };
}

function send(socket, message) {
  socket.write(`${JSON.stringify(message)}\n`);
}

function terminalOptions(terminalId, cwd) {
  return {
    workspaceId: terminalId,
    cwd,
    cols: 80,
    rows: 24,
    scrollbackLines: 100,
  };
}

function ptyAvailable() {
  try {
    const terminal = pty.spawn(process.execPath, ["--version"], {
      cwd: process.cwd(),
      cols: 80,
      rows: 24,
      env: process.env,
    });
    terminal.kill();
    return true;
  } catch {
    return false;
  }
}

async function nextTerminalReady(reader, options = {}) {
  for (let index = 0; index < 10; index += 1) {
    const message = await reader.next();
    if (message.type === "terminal_ready") {
      return message;
    }
    if (options.rejectTerminalExit && message.type === "terminal_exit") {
      throw new Error("terminal_exit received during restart");
    }
  }
  throw new Error("terminal_ready not received");
}

async function expectTerminalOutput(reader, expectedText, options = {}) {
  for (let index = 0; index < 10; index += 1) {
    const message = await reader.next();
    if (message.type === "terminal_data" && message.data.includes(expectedText)) {
      return;
    }
    if (message.type === "terminal_exit" && options.rejectTerminalExit) {
      throw new Error("terminal_exit received during restart");
    }
    if (message.type === "error") {
      throw new Error(message.error);
    }
  }
  throw new Error(`${expectedText} not received`);
}

test("terminal environment uses an explicit allowlist", () => {
  process.env.YINSHI_TERMINAL_SECRET = "terminal-secret-must-not-leak";
  process.env.NPM_CONFIG_PREFIX = "/home/yinshi/.npm-global";
  try {
    const environment = buildTerminalEnvironment("/data/workspace", "/bin/bash");

    assert.equal(environment.YINSHI_TERMINAL_SECRET, undefined);
    assert.equal(environment.NPM_CONFIG_PREFIX, "/home/yinshi/.npm-global");
    assert.equal(environment.PWD, "/data/workspace");
    assert.equal(environment.SHELL, "/bin/bash");
    assert.equal(environment.TERM, "xterm-256color");
  } finally {
    delete process.env.YINSHI_TERMINAL_SECRET;
    delete process.env.NPM_CONFIG_PREFIX;
  }
});

test("terminal attach starts a PTY and streams output", async (t) => {
  if (!ptyAvailable()) {
    t.skip("node-pty cannot spawn on this host runtime");
    return;
  }
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "yinshi-terminal-test-"));
  const socketPath = path.join(tempDir, "sidecar.sock");
  const terminalId = "a".repeat(32);
  process.env.SIDECAR_SOCKET_PATH = socketPath;
  process.env.YINSHI_TERMINAL_SECRET = "terminal-secret-must-not-leak";
  const sidecar = new YinshiSidecar();
  await sidecar.start();

  const socket = net.createConnection(socketPath);
  const reader = createMessageReader(socket);
  try {
    const init = await reader.next();
    assert.equal(init.type, "init_status");

    send(socket, {
      type: "terminal_attach",
      id: terminalId,
      options: terminalOptions(terminalId, tempDir),
    });
    const ready = await nextTerminalReady(reader);
    assert.equal(ready.cwd, tempDir);

    send(socket, {
      type: "terminal_input",
      id: terminalId,
      data: "printf YINSHI_TERMINAL_TEST\\n\n",
    });

    await expectTerminalOutput(reader, "YINSHI_TERMINAL_TEST");

    send(socket, {
      type: "terminal_input",
      id: terminalId,
      data: "env | grep YINSHI_TERMINAL_SECRET || printf NO_SECRET\\n\n",
    });

    let sawNoSecret = false;
    for (let index = 0; index < 10; index += 1) {
      const message = await reader.next();
      if (message.type !== "terminal_data") {
        continue;
      }
      assert.equal(message.data.includes("terminal-secret-must-not-leak"), false);
      if (message.data.includes("NO_SECRET")) {
        sawNoSecret = true;
        break;
      }
    }
    assert.equal(sawNoSecret, true);

    send(socket, {
      type: "terminal_restart",
      id: terminalId,
      options: terminalOptions(terminalId, tempDir),
    });
    await nextTerminalReady(reader, { rejectTerminalExit: true });
    send(socket, {
      type: "terminal_input",
      id: terminalId,
      data: "printf YINSHI_TERMINAL_RESTART\\n\n",
    });
    await expectTerminalOutput(reader, "YINSHI_TERMINAL_RESTART", { rejectTerminalExit: true });
  } finally {
    reader.dispose();
    socket.destroy();
    sidecar.cleanup();
    delete process.env.YINSHI_TERMINAL_SECRET;
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
});

test("terminal attach rejects invalid workspace ids", async () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "yinshi-terminal-test-"));
  const socketPath = path.join(tempDir, "sidecar.sock");
  process.env.SIDECAR_SOCKET_PATH = socketPath;
  const sidecar = new YinshiSidecar();
  await sidecar.start();

  const socket = net.createConnection(socketPath);
  const reader = createMessageReader(socket);
  try {
    await reader.next();
    send(socket, {
      type: "terminal_attach",
      id: "bad",
      options: { workspaceId: "bad", cwd: tempDir },
    });
    const error = await reader.next();
    assert.equal(error.type, "error");
    assert.match(error.error, /workspaceId/);
  } finally {
    reader.dispose();
    socket.destroy();
    sidecar.cleanup();
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
});

