 81	  checked_at: new Date().toISOString(),
 82	  status: process.env.STATUS_VALUE || "unknown",
 83	  previous_version: process.env.PREVIOUS_VERSION || null,
 84	  current_version: process.env.CURRENT_VERSION || null,
 85	  latest_version: process.env.LATEST_VERSION || null,
 86	  updated: process.env.UPDATED_VALUE === "true",
 87	  message: process.env.MESSAGE_VALUE || null,
 88	};
 89	fs.mkdirSync(path.dirname(statusPath), { recursive: true });
 90	const temporaryPath = `${statusPath}.tmp`;
 91	fs.writeFileSync(temporaryPath, `${JSON.stringify(payload, null, 2)}\n`, "utf-8");
 92	fs.renameSync(temporaryPath, statusPath);
 93	NODE
 94	}
 95	
 96	read_installed_version() {
 97	  local package_root="$1"
 98	  PACKAGE_ROOT="$package_root" PACKAGE_NAME="$package_name" node --input-type=module <<'NODE'
 99	import fs from "node:fs";
100	import path from "node:path";
101	
102	const packageRoot = process.env.PACKAGE_ROOT;
103	const packageName = process.env.PACKAGE_NAME;
104	if (!packageRoot || !packageName) {
105	  process.exit(2);
106	}
107	let currentPath = path.join(packageRoot, "src");
108	while (true) {
109	  const packageJsonPath = path.join(currentPath, "node_modules", packageName, "package.json");
110	  if (fs.existsSync(packageJsonPath)) {
111	    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf-8"));
112	    if (packageJson.name === packageName) {
113	      process.stdout.write(packageJson.version || "");
114	      process.exit(packageJson.version ? 0 : 4);
115	    }
116	  }
117	  const parentPath = path.dirname(currentPath);
118	  if (parentPath === currentPath) {
119	    break;
120	  }
121	  currentPath = parentPath;
122	}
123	process.exit(5);
124	NODE
125	}
126	
127	copy_sidecar_context() {
128	  local target_dir="$1"
129	  cp "$sidecar_dir/package.json" "$target_dir/package.json"
130	  cp "$sidecar_dir/package-lock.json" "$target_dir/package-lock.json"
131	  cp "$sidecar_dir/Dockerfile" "$target_dir/Dockerfile"
132	  cp -R "$sidecar_dir/src" "$target_dir/src"
133	}
134	
135	run_smoke_test() {
136	  local target_dir="$1"
137	  (cd "$target_dir" && node --input-type=module <<'NODE'
138	import { pathToFileURL } from "node:url";
139	import { AuthStorage, ModelRegistry } from "@mariozechner/pi-coding-agent";
140	
141	const registry = new ModelRegistry(AuthStorage.inMemory(), null);
142	const models = registry.getAll();
143	if (!Array.isArray(models)) {
144	  throw new Error("Model registry did not return an array");
145	}
146	if (models.length === 0) {
147	  throw new Error("Model registry returned no models");
148	}
149	const sidecarModule = await import(pathToFileURL(`${process.cwd()}/src/sidecar.js`).href);
150	if (typeof sidecarModule.YinshiSidecar !== "function") {
151	  throw new Error("YinshiSidecar export is missing");
152	}
153	const sidecar = new sidecarModule.YinshiSidecar();
154	sidecar.cleanup();
155	NODE
156	  )
157	}
158	
159	replace_node_modules() {
160	  local source_node_modules="$1"
161	  local target_node_modules="$2"
162	  local next_node_modules="$target_node_modules.next"
163	  local previous_node_modules="$target_node_modules.previous"
164	
165	  rm -rf "$next_node_modules" "$previous_node_modules" || return 1
166	  cp -a "$source_node_modules" "$next_node_modules" || return 1
167	  if [[ -d "$target_node_modules" ]]; then
168	    mv "$target_node_modules" "$previous_node_modules" || {
169	      rm -rf "$next_node_modules"
170	      return 1
171	    }
172	  fi
173	  mv "$next_node_modules" "$target_node_modules" || {
174	    if [[ -d "$previous_node_modules" ]]; then
175	      mv "$previous_node_modules" "$target_node_modules" || true
176	    fi
177	    rm -rf "$next_node_modules"
178	    return 1
179	  }
180	  rm -rf "$previous_node_modules" || return 1
181	}
182	
183	previous_version=""
184	latest_version=""
185	resolved_version=""
186	temporary_dir=""
187	
188	fail_update() {
189	  local message_value="$1"
190	  write_status "failed" "false" "$previous_version" "$resolved_version" "$latest_version" "$message_value"
191	  echo "$message_value" >&2
192	  exit 1
193	}
194	
195	mkdir -p "$runtime_dir"
196	if ! command -v flock >/dev/null 2>&1; then
197	  fail_update "flock is required"
198	fi
199	exec 9>"$lock_path"
200	if ! flock -n 9; then
201	  log "Another pi package update is already running; exiting."
202	  exit 0
203	fi
204	
205	cleanup() {
206	  if [[ -n "$temporary_dir" && -d "$temporary_dir" ]]; then
207	    rm -rf "$temporary_dir"
208	  fi
209	}
210	trap cleanup EXIT
211	
212	if [[ ! -d "$sidecar_dir" ]]; then
213	  fail_update "Sidecar directory not found: $sidecar_dir"
214	fi
215	if ! command -v npm >/dev/null 2>&1; then
216	  fail_update "npm is required"
217	fi
218	if ! command -v podman >/dev/null 2>&1; then
219	  fail_update "podman is required to rebuild tenant sidecar image"
220	fi
221	
222	previous_version="$(read_installed_version "$sidecar_dir" || true)"
223	if ! latest_version="$(npm view "$package_name" version --silent)"; then
224	  fail_update "npm view failed for $package_name"
225	fi
226	if [[ -z "$latest_version" ]]; then
227	  fail_update "npm did not return a latest version for $package_name"
228	fi
229	
230	if [[ -n "$previous_version" && "$previous_version" == "$latest_version" ]]; then
231	  write_status "current" "false" "$previous_version" "$previous_version" "$latest_version" "$package_name is already current"
232	  log "$package_name is already current at $latest_version."
233	  exit 0
234	fi
235	
236	temporary_dir="$(mktemp -d)"
237	copy_sidecar_context "$temporary_dir"
238	log "Updating $package_name from ${previous_version:-not installed} to $latest_version in temporary build context."
239	if ! npm install --prefix "$temporary_dir" --omit=dev --no-audit --no-fund "$package_name@$latest_version"; then
240	  fail_update "npm install failed for $package_name@$latest_version"
241	fi
242	if ! resolved_version="$(read_installed_version "$temporary_dir")"; then
243	  fail_update "Could not read installed version after npm install"
244	fi
245	if [[ "$resolved_version" != "$latest_version" ]]; then
246	  fail_update "Resolved $resolved_version instead of npm latest $latest_version"
247	fi
248	
249	if ! run_smoke_test "$temporary_dir"; then
250	  fail_update "Sidecar smoke test failed for $package_name@$latest_version"
251	fi
252	if ! podman build -t "$container_image" "$temporary_dir"; then
253	  fail_update "Podman image build failed for $container_image"
254	fi
255	if ! replace_node_modules "$temporary_dir/node_modules" "$sidecar_dir/node_modules"; then
256	  fail_update "Failed to replace host sidecar node_modules"
257	fi
258	write_status "updated" "true" "$previous_version" "$resolved_version" "$latest_version" "Updated $package_name to $resolved_version and rebuilt $container_image"
259	log "Updated $package_name to $resolved_version and rebuilt $container_image."

